maintenanceTypesInfo = self.view.custom.maintenanceTypes.selected
if maintenanceTypesInfo and maintenanceTypesInfo.has_key('maintenanceTypeId'):
	retVal, msg = system.kanoa.cmms.deleteMaintenanceType(maintenanceTypesInfo['maintenanceTypeId'], self.view.custom.security.userId)
	if retVal:
		system.perspective.sendMessage('showSuccessfulToast', {'message': 'Maintenance type has been deleted'})
	else:
		if 'The DELETE statement conflicted with the REFERENCE constraint' in str(msg) or 'The DELETE statement conflicted with the SAME TABLE REFERENCE constraint' in str(msg):
